import{_ as l,a0 as r,w as i,s as C,ao as u,I as s,x as o,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Linus Torvalds坦言所有CLA都不夠完美，Canonical有話説 | LCTT x X-CMD","titleTemplate":false,"description":"Linus Torvalds坦言所有CLA都不夠完美，Canonical有話説 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linus Torvalds坦言所有CLA都不夠完美，Canonical有話説 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linus Torvalds坦言所有CLA都不夠完美，Canonical有話説 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Linus Torvalds Says All Contributor License Agreements Are Broken","title":"Linus Torvalds坦言所有CLA都不夠完美，Canonical有話説","tag":"201401","desc":""},"relativePath":"201401/Linus Torvalds Says All Contributor License Agreements Are Broken.md","filePath":"[post].md"}'),p={name:"201401/Linus Torvalds Says All Contributor License Agreements Are Broken.md"};function L(A,n,d,T,m,c){const t=r("Link");return i(),C("div",null,[n[11]||(n[11]=u('<h1 id="linus-torvalds坦言所有cla都不夠完美-canonical有話説" tabindex="-1">Linus Torvalds坦言所有CLA都不夠完美，Canonical有話説 <a class="header-anchor" href="#linus-torvalds坦言所有cla都不夠完美-canonical有話説" aria-label="Permalink to “Linus Torvalds坦言所有CLA都不夠完美，Canonical有話説”">​</a></h1><p><strong>一場關於 Canonical 公司的貢獻者許可協議的爭論已經持續了好幾天，現在連 Linus Torvalds 也加入這場論戰了，呃，這次他比較心平氣和了一點。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Linus-Torvalds-Says-All-Contributor-License-Agreements-Are-Broken-418978-2.jpg" alt=""></p><p>貢獻者許可協議（CLA）允許你的軟件貢獻者（比如 Canonical，Apache 以及其他貢獻者）在這個應用需要保護的方面提供法律保護，比如版權。</p><p>到了 Canonical 宣佈使用 CLA，事情就變得有點耐人尋味了。Canonical 是一家商業公司，為了生存下去，它得賺錢，並且它的目標絕不僅僅是發行 Ubuntu 操作系統，它需要盈利。於是乎，Canonical 公司利用 CLA 將一些軟件通過私有許可發行出來。（2011年7月份，Canonical 開始讓貢獻者簽署一份 CLA 文件，文件表示貢獻者可以保留自己的版權，同時要授權 Canonical 公司可以改變貢獻者的許可協議 —— 譯者注。）</p><blockquote><p>“公平地説，人們只是討厭 Canonical。那些 FSF 和 Apache 基金會的 CLA 也是這副德行。他們只是沒有因為修改許可協議而受到非議，但是這些版權轉換工作最終將會消滅整個社區。”</p></blockquote><blockquote><p>“基本上，在 CLA 下你不可能獲得像 Linux 內核一樣那麼多的隨機驅動補丁。因此不管多少人想試水 CLA，不管改不改這個協議，都一樣，所有 CLA 都有本質上的缺陷，”Linus Torvals 在 Google+ 上面發帖説道。</p></blockquote><p>Ubuntu 社區經理 Jono Bacon 解釋為什麼 Canonical 的 CLA 會走這條道，以及它不能給那些想為項目作貢獻的人設置障礙的原因。</p><blockquote><p>“這些都是社區貢獻的問題。社區一直存在很多問題：開發語言的選擇、VCS、管理方式、社區討論的口音、如何決定方案、如何回顧分支、bug 管理、CI 工作流程以及其他無數問題。CLA 僅僅是其中一個。有人歡喜，有人討厭，蘿蔔青菜各有所愛罷了。”</p></blockquote><blockquote><p>“我不認為 Canonical 在 CLA 方面表現得不夠誠意，也不關心為什麼它會認為它的 CLA 方案很有必要。Canonical 在人們印象中是完美無瑕的嗎？不見得。那它危險嗎？它虛偽嗎？當然不。”Jono Bacon 説道。</p></blockquote><hr>',11)),s("p",null,[n[1]||(n[1]=o("via: ",-1)),e(t,{href:"http://news.softpedia.com/news/Linus-Torvalds-Says-All-Contributor-License-Agreements-Are-Broken-418978.shtml"},{default:a(()=>[...n[0]||(n[0]=[o("http://news.softpedia.com/news/Linus-Torvalds-Says-All-Contributor-License-Agreements-Are-Broken-418978.shtml",-1)])]),_:1})]),s("p",null,[n[4]||(n[4]=o("譯者：",-1)),e(t,{href:"https://github.com/bazz2"},{default:a(()=>[...n[2]||(n[2]=[o("bazz2",-1)])]),_:1}),n[5]||(n[5]=o(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...n[3]||(n[3]=[o("wxy",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=o("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...n[6]||(n[6]=[o("LCTT",-1)])]),_:1}),n[9]||(n[9]=o(" 原創翻譯，",-1)),e(t,{href:"http://linux.cn/"},{default:a(()=>[...n[7]||(n[7]=[o("Linux中國",-1)])]),_:1}),n[10]||(n[10]=o(" 榮譽推出",-1))])])}const v=l(p,[["render",L]]);export{g as __pageData,v as default};
